def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_opp_bids = []

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_opp_bids.append(float(bid))

    if not alive_opps:
        base = 18.0 if hp > 3 else 42.0
        return float(max(0.0, min(budget, base)))

    scarcity = (float(supply) - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    tightness = 1.0 - scarcity

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else highest_prev

    hp_risk = 0.0
    if hp <= 2:
        hp_risk = 1.0
    elif hp <= 4:
        hp_risk = 0.6
    elif hp <= 6:
        hp_risk = 0.3

    dehydration_risk = 0.5 if no_water_days >= 1 else 0.0
    danger = max(hp_risk, dehydration_risk)

    if danger >= 1.0:
        target = max(urgent_prev + 2.0, 0.92 * DAILY_SALARY)
    elif tightness >= 0.7:
        target = max(highest_prev + 1.5, 0.78 * DAILY_SALARY)
    elif tightness >= 0.4:
        target = max(highest_prev * 0.72, 0.56 * DAILY_SALARY)
    else:
        target = max(highest_prev * 0.42, 0.28 * DAILY_SALARY)

    if day >= 8:
        target *= 1.08
    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget * 0.72)
    elif budget < DAILY_SALARY * 2.0:
        target = min(target, budget * 0.82)

    if hp >= 8 and tightness < 0.35:
        target *= 0.9

    target = max(0.0, min(float(budget), float(target)))
    return float(target)

