def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids for immediate reaction
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure heuristic: if supply is closer to max, more likely others bid higher.
    # Normalize supply to [0,1]
    denom = (MAX_SUPPLY - MIN_SUPPLY) if (MAX_SUPPLY - MIN_SUPPLY) != 0 else 1.0
    supply_norm = (supply - MIN_SUPPLY) / denom
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Base bid targets
    # - If our hp is low or no-water days high, we must bid more.
    # - Otherwise, bid moderately to avoid being the budget-donor.
    low_hp = my_hp <= 2
    urgent = (my_no_water_days >= 2)

    # If yesterday someone bid very high, they likely spent aggressively; we counter only moderately.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85

    if low_hp or urgent:
        target = DAILY_SALARY * (0.85 + 0.1 * supply_norm)
    else:
        if high_pressure:
            # Keep just below the peak pressure to reduce our burn rate.
            target = min(DAILY_SALARY * (0.55 + 0.15 * supply_norm), highest_prev_bid * 0.85)
        else:
            target = DAILY_SALARY * (0.45 + 0.25 * supply_norm)

    # Convert to feasible bid
    bid = min(my_budget, target)

    # If supply is low-ish (near MIN_SUPPLY), slightly reduce to avoid waste.
    if supply <= (MIN_SUPPLY + 2.0):
        bid *= 0.9

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

