        base_bid *= 1.1
    elif day_context['supply'] > total_water_demand * 1.5:
        base_bid *= 0.9

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] > 5 and my_status['budget'] > DAILY_SALARY * 2:
            base_bid *= 1.2
        elif my_status['hp'] <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 1.5)

