    if my_status['hp'] <= 2 and my_status['budget'] > 0:
        final_bid = max(final_bid, my_status['budget'] * 0.95)
    elif final_bid < DAILY_SALARY * 0.1 and my_status['budget'] > 0:
        final_bid = max(final_bid, DAILY_SALARY * 0.1)

    return final_bid

